INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_HTT_ALALU_HITTIT','ENT_HTT_ALALU','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','Hoffner, Hittite Myths','Alalu, driven from his throne by Anu, is the father of Kumarbi, who in turn drives Anu from his throne. Furthermore, when Kumarbi emasculates Anu to forestall his own removal by any descendant of Anu, he inadvertently makes his own belly the womb for Anu''s seed, which pro- duces Tessub, Tasmisu, the Aranzah River, and several other gods.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_ARANZAH_HITTIT','ENT_HTT_ARANZAH','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','Hoffner, Hittite Myths','tently makes his own belly the womb for Anu''s seed, which pro- duces Tessub, Tasmisu, the Aranzah River, and several other gods. Although the end of the Song of Kumarbi is lost, everyone agrees that, since the Song of Ullikummi finds Tessub as king of the gods, he may have already attained that position by the end of the Song of Kumarbi.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_ARINNA_HITTIT','ENT_HTT_ARINNA','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','Hoffner, Hittite Myths','Sun Goddess of Arinna The chief goddess in the New Hittite pantheon, whose consort was the great Storm God. In the New Kingdom they were identified with Hebat and Tessub. Sun Goddess of the Earth (=nether world) Her name in Old Hittite, Hattian contexts is unknown.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_HANNAHANNA_HITTIT','ENT_HTT_HANNAHANNA','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','CTH 324',': 1987 "La deesse Hannahanna: son image et sa place dans les mythes anatoliens." Hetbitica 7: 109-48. Kirk, G. S. 1970 Myth: Its Meaning and Functions in Ancient and Other Cultures. Berkeley: University of California Press. Komoreczy, G. 1973 "The Separation of Sky and Earth'': The Cycle of Kumarbi and the Myths of Cosmogony in Mesopotamia." Acta Antiqua 21:21--45. Kiihne, C. 1978 "Hittite Texts." Pp.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_HAZZI_HITTIT','ENT_HTT_HAZZI','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','Hoffner, Hittite Myths','The Hurrian myths of the Kumarbi Cycle are set in Upper Mesopotamia (Urkis, Kummiya), North Syria (Tuttul) and along the eastern coast of the Mediterranean (Mount Hazzi=Mount Kasios). Hittite rulers prided themselves on the internal diversity of their culture. Religious syncretism provided the means to assimilate new groups.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_ILLUYANKA_HITTIT','ENT_HTT_ILLUYANKA','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','CTH 321','Both ver- sions of the Illuyanka stories show consequences flowing from the major plot of the Storm God''s recovery of his strength and defeat of the serpent. These conse- quences fall tragically upon a mortal who is the instrument of the Storm God''s vic- tory. In both stories this mortal is confronted with a conflict of allegiances, a kind of moral dilemma.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_KAMRUSEPA_HITTIT','ENT_HTT_KAMRUSEPA','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','Hoffner, Hittite Myths','Kamrusepa Myths 33 11. The Voyage of the Immortal Human Soul 33 12. When the Storm God Thunders Frightfully 34 13. Fragments of Myths about Lost and Found Deities 37 HURRIAN MYTHS AO 14. The Song of Kumarbi 42 15. The Song of the God LAMMA A6 16. The Song of Silver A8 17. The Song of Hedammu 50 18. The Song of Ullikummi 55 18a. The Song of Release 65 TALES INVOLVING DEITIES AND MORTALS 81 19. A Tale of Two Cities: Kanesh and Zalpa 81 20.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_KUMARBI_HITTIT','ENT_HTT_KUMARBI','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','CTH 344','Hoffner (1988b) reconstructed the myth about the personified Silver (Text 16), demonstrating that this story too was a "song" belonging to the Kumarbi series. We know from colophons that in the native terminology Text 18 was called the Song of Ullikummi, and Text 14 the Song of Ku[marbi]. The Silver myth''s proemium contains the statement ishamibhi "I sing," which shows it to be the Song of Silver.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_SERI_HURRI_HITTIT','ENT_HTT_SERI_HURRI','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','Hoffner, Hittite Myths','Seri and Hurri The divine bulls who draw Tessub''s cart. Sun God In Old Hittite myths he is the Hattian solar deity Estan, son of the Great Storm God and brother of Telipinu. In New Hittite Kumarbi myths he is the Hurrian solar deity Simige, an ally of Tessub. Sun Goddess of Arinna The chief goddess in the New Hittite pantheon, whose consort was the great Storm God. In the New Kingdom they were identified with Hebat and Tessub.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_TELIPINU_HITTIT','ENT_HTT_TELIPINU','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','CTH 324-325','The Telipinu myth is the best preserved and most familiar of this type. Telipinu was the son of the great Storm God. His competence lay in fostering agriculture, particularly cereal cul- ture. Compare Text 7, §6. He shows his anger with thunder and lightning (Text 2, version 1, §16). Therefore, although his usual designation is by his Hattic name, Telipinu, he is clearly a Storm God.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_HTT_ULLIKUMMI_HITTIT','ENT_HTT_ULLIKUMMI','SRC_HOFFNER_HITTITE_MYTHS','Hoffner, Hittite Myths','CTH 345','40 Hurrian Myths 4] Kumarbi, Song of LAMMA, Song of Silver, Song of Hedammu, and Song of Ullikummi. | The central theme of the entire cycle is the competition between Kumarbi and - Tessub for kingship over the gods. As pointed out by Hoffner (1975:136-45), the sequence of divine rulers in the Song of Kumarbi is not a father, son, grandson, but an alternation of two competing lines.','H. A. Hoffner Jr.',1998,'None',NULL,'primary-verbatim',NULL,true,'In-copyright translation — brief flagged excerpt; verify.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
